// ---------------------------------------------------------------------------
// Emergency resource guard
//
// node_critical_pct (default 90) is a routine, tolerated state for this
// fleet — nodes run hot at 90-95% RAM with no real problem (confirmed live
// 2026-09-14). What actually crashed a node that same day was different:
// physical RAM genuinely ran out, the kernel OOM-killer picked a VM at
// effectively random, and the resulting thrash was severe enough to trigger
// a hardware-watchdog reboot of the WHOLE node — every customer on it, not
// just the one VM that was using the most memory.
//
// This sweep is the backstop for that specific failure mode: when a node's
// REAL RAM usage stays above node_emergency_pct (default 97 — deliberately
// far above the routine-but-tolerated CRITICAL line) for two consecutive
// sweeps, it reboots the single largest customer VM on that node itself,
// under our own control, instead of leaving the choice to the kernel. A
// controlled, one-VM reboot that the customer is told about beats an
// uncontrolled, whole-node crash every time.
//
// Never triggers on "this VM exceeds ITS OWN plan" — a VM over its own
// allocation on a node with slack is normal and untouched; only the node's
// real, aggregate pressure matters here.
// ---------------------------------------------------------------------------

/** node.id -> consecutive sweeps seen at/above the emergency line. Resets on
 *  a worker restart, which only means "start the streak over" — never wrong,
 *  just occasionally slower to trigger right after a deploy. */
const emergencyStreak = new Map<string, number>();

/** server.id -> ms epoch of the last auto-reboot, kept in-process only as a
 *  fast pre-check; the durable source of truth is gameConfig._lastResourceReboot
 *  (below), which survives a worker restart and is what's actually enforced. */
const RESOURCE_REBOOT_COOLDOWN_MS = 45 * 60_000;
const REBOOT_TASK_TIMEOUT_MS = 60_000;

export async function resourceGuardSweep(): Promise<void> {
  if (SANDBOX) return; // no real nodes/VMs to reboot in the sandbox

  const emergencyPct = await getSettingInt("node_emergency_pct", 97);

  const nodes = await db.node.findMany({ where: { enabled: true } });
  for (const n of nodes) {
    let client: ReturnType<typeof pveFor>;
    let hostStatus: any;
    try {
      client = pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
      hostStatus = await client.get(`/nodes/${n.pveNode}/status`);
    } catch (e) {
      console.error(`[resource-guard] could not reach node ${n.name}`, e);
      continue; // unreachable is not the same as "safe" — but with no data, do nothing
    }

    const total = Number(hostStatus?.memory?.total ?? 0);
    const used = Number(hostStatus?.memory?.used ?? 0);
    const pct = total > 0 ? (used / total) * 100 : 0;

    if (pct < emergencyPct) {
      emergencyStreak.delete(n.id);
      continue;
    }
    const streak = (emergencyStreak.get(n.id) ?? 0) + 1;
    emergencyStreak.set(n.id, streak);
    if (streak < 2) continue; // one bad sample isn't proof — wait for the next sweep to confirm

    // Sustained emergency confirmed. Reset now so a second reboot on this node
    // requires two FRESH consecutive readings, not one leftover from this trigger.
    emergencyStreak.set(n.id, 0);

    let vms: any[];
    try {
      vms = await client.get(`/nodes/${n.pveNode}/qemu`);
    } catch (e) {
      console.error(`[resource-guard] could not list VMs on ${n.name}`, e);
      continue;
    }
    const running = (vms ?? []).filter((v) => v.status === "running" && Number.isFinite(v.vmid));
    if (running.length === 0) continue;

    const vmids = running.map((v) => Number(v.vmid));
    const servers = await db.server.findMany({
      where: { vmid: { in: vmids } },
      select: { id: true, userId: true, hostname: true, vmid: true, status: true, gameConfig: true },
    });
    const serverByVmid = new Map(servers.map((s) => [s.vmid, s]));

    // Only ever consider VMs we actually track as a customer Server — never an
    // untracked/platform VM (mail, admin apps, an orphan like darkeden-guard-sg
    // found live 2026-09-14, etc.), and never one already flagged non-RUNNING.
    const candidates = running
      .map((v) => ({ vm: v, server: serverByVmid.get(Number(v.vmid)) }))
      .filter((c) => c.server && c.server.status === "RUNNING")
      .sort((a, b) => Number(b.vm.mem ?? 0) - Number(a.vm.mem ?? 0));

    if (candidates.length === 0) {
      console.error(`[resource-guard] ${n.name} is at ${Math.round(pct)}% RAM with no trackable VM to act on`);
      continue;
    }

    const top = candidates[0];
    const server = top.server!;
    const cfg = (server.gameConfig as Record<string, unknown> | null) ?? {};
    const lastRebootIso = cfg._lastResourceReboot as string | undefined;
    const lastRebootMs = lastRebootIso ? new Date(lastRebootIso).getTime() : 0;
    const inCooldown = Date.now() - lastRebootMs < RESOURCE_REBOOT_COOLDOWN_MS;

    if (inCooldown) {
      // Already actioned recently and STILL the top consumer on a node still in
      // trouble — a human needs to look at this, not us reboot it again so soon.
      await notifyNodeCapacity(
        `Node still critical after a recent auto-reboot — ${n.name}`,
        `${n.name} is at ${Math.round(pct)}% RAM. ${server.hostname} (the largest VM on it) was already ` +
          `auto-rebooted within the last ${Math.round(RESOURCE_REBOOT_COOLDOWN_MS / 60_000)} minutes and is ` +
          `still the top consumer — needs manual attention rather than another automatic reboot.`,
      );
      continue;
    }

    const memGB = (Number(top.vm.mem ?? 0) / 1024 ** 3).toFixed(1);
    console.error(
      `[resource-guard] ${n.name} at ${Math.round(pct)}% RAM (sustained) — rebooting ${server.hostname} ` +
        `(vmid ${server.vmid}, ${memGB} GB, largest on node)`,
    );

    let rebootOk = true;
    try {
      const upid = await client.post(`/nodes/${n.pveNode}/qemu/${server.vmid}/status/reboot`, {});
      await client.waitForTask(upid, REBOOT_TASK_TIMEOUT_MS);
    } catch (e) {
      // ACPI reboot can hang a guest that's itself thrashing under memory
      // pressure — fall back to a hard stop+start rather than leave it wedged.
      console.error(`[resource-guard] graceful reboot of ${server.hostname} did not finish cleanly, forcing`, e);
      try {
        const stopUpid = await client.post(`/nodes/${n.pveNode}/qemu/${server.vmid}/status/stop`, {});
        await client.waitForTask(stopUpid, REBOOT_TASK_TIMEOUT_MS);
        const startUpid = await client.post(`/nodes/${n.pveNode}/qemu/${server.vmid}/status/start`, {});
        await client.waitForTask(startUpid, REBOOT_TASK_TIMEOUT_MS);
      } catch (e2) {
        rebootOk = false;
        console.error(`[resource-guard] forced stop+start of ${server.hostname} also failed`, e2);
      }
    }

    try {
      await db.server.update({
        where: { id: server.id },
        data: { gameConfig: { ...cfg, _lastResourceReboot: new Date().toISOString() } },
      });
    } catch (e) {
      console.error(`[resource-guard] could not persist cooldown marker for ${server.hostname}`, e);
    }

    if (rebootOk) {
      try {
        await db.notification.create({
          data: {
            userId: server.userId,
            title: `${server.hostname} was automatically restarted`,
            body: "Your server was using more resources than usual while the node it runs on was critically low on memory, so we restarted it to keep things stable for every server on that machine.",
            href: `/dashboard/servers/${server.id}`,
          },
        });
      } catch (e) {
        console.error(`[resource-guard] in-app notify failed for ${server.hostname}`, e);
      }
      try {
        const { emails } = await import("../lib/email-templates");
        const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
        if (user?.email) {
          const tpl = emails.autoResourceReboot({ hostname: server.hostname });
          await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, template: tpl.template, userId: server.userId });
        }
      } catch (e) {
        console.error(`[resource-guard] email notify failed for ${server.hostname}`, e);
      }
    }

    await notifyNodeCapacity(
      rebootOk ? `Emergency auto-reboot — ${n.name}` : `Emergency auto-reboot FAILED — ${n.name}`,
      `${n.name} was at ${Math.round(pct)}% RAM (sustained). ${server.hostname} (vmid ${server.vmid}) was the ` +
        `largest VM on it at ${memGB} GB and was ${rebootOk ? "automatically rebooted" : "targeted for an automatic reboot, but it FAILED — needs manual attention"}.`,
    );
  }
}

