import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { pveForNode } from "../lib/proxmox";
import { notifyAdmins } from "./monitor";

/**
 * VM power-state reconciliation — the layer that was missing on 2026-09-10.
 *
 * The primary node suffered a hard, ungraceful crash-and-reboot. Proxmox's
 * own `onboot=1` + `startall` correctly auto-started every VM except one
 * (`studionexis-soul`, the live Soul Pilates production site): its cloud-init
 * ZFS dataset hit a transient "already exists" collision from the crash, the
 * start attempt failed, and NOTHING retried it or even noticed — the VM sat
 * stopped, silently, until a human found it by hand. Every other reliability
 * sweep in this file assumes the VM is already running (`sshHealthSweep`
 * checks whether SSH still authenticates on a RUNNING server; it never checks
 * whether the VM is actually powered on at all). This sweep closes that gap:
 * whenever `Server.status` says RUNNING but Proxmox disagrees, retry the
 * start and tell an admin either way.
 *
 * Deliberately simple, matching `sshHealthSweep`'s own shape: no backoff
 * bookkeeping, just "check every sweep, retry every sweep, notifyAdmins is
 * already dedup'd on its own (DEDUPE_HOURS) so a stuck VM doesn't spam" — a
 * genuinely stuck VM (like the ZFS collision) needs a human regardless, and
 * repeated retries are harmless (Proxmox's start is a no-op on an
 * already-running VM, and a fresh cloud-init generation on retry is exactly
 * what fixed the real 2026-09-10 case).
 */
const BATCH_SIZE = 40;
let cursor = 0;

export async function vmRecoverySweep(): Promise<void> {
  if (SANDBOX) return; // no real Proxmox in staging

  const where = { status: "RUNNING" as const, vmid: { not: null } };
  const total = await db.server.count({ where });
  if (total === 0) return;
  if (cursor >= total) cursor = 0;

  const servers = await db.server.findMany({
    where,
    include: {
      node: true,
      user: { select: { email: true } },
    },
    orderBy: { id: "asc" },
    skip: cursor,
    take: BATCH_SIZE,
  });
  cursor += servers.length;
  if (servers.length < BATCH_SIZE) cursor = 0; // wrapped past the end of the table

  for (const s of servers) {
    if (!s.vmid) continue;
    try {
      const conn = s.node
        ? pveForNode({ apiUrl: s.node.apiUrl, pveNode: s.node.pveNode, tokenId: s.node.tokenId, tokenSecret: s.node.tokenSecret })
        : null;
      if (!conn) continue; // no Node row yet on a legacy server — nothing safe to check against

      const current = await conn.vmStatus(s.vmid);
      const realStatus = (current as any)?.status;
      if (realStatus === "running") continue; // the common case — nothing to do

      // Proxmox disagrees with our own record: the VM is down when it should
      // be up. Attempt the same recovery a human would do by hand.
      console.error(`[vm-recovery] ${s.hostname} (vmid ${s.vmid}) is "${realStatus}" but Server.status is RUNNING — attempting start`);
      try {
        await conn.post(`/nodes/${conn.node}/qemu/${s.vmid}/status/start`, {});
        await notifyAdmins(
          `Auto-recovered: ${s.hostname} was down`,
          `"${s.hostname}" (customer ${s.user.email}, vmid ${s.vmid}) was found powered off (Proxmox status: "${realStatus}") while marked RUNNING — likely fallout from a host restart. It has been started back up automatically. Worth a quick look to confirm the guest's own services (database, app, game process) came back cleanly too, not just the VM shell.`,
          `/admin/servers/${s.id}`
        );
      } catch (startErr: any) {
        await notifyAdmins(
          `VM down and won't restart: ${s.hostname}`,
          `"${s.hostname}" (customer ${s.user.email}, vmid ${s.vmid}) is powered off (Proxmox status: "${realStatus}") and the automatic restart attempt failed: ${startErr?.message ?? startErr}. This needs a human — check /admin/servers/${s.id} or SSH to the node directly.`,
          `/admin/servers/${s.id}`
        );
      }
    } catch (e: any) {
      // A probe failure (node unreachable, etc.) — don't let one bad server
      // stop the rest of the batch, and don't spam if the whole node is down
      // (nodeAlert/capacity sweeps already own that signal).
      console.error(`[vm-recovery] probe failed for ${s.hostname} (${s.id}):`, e?.message ?? e);
    }
  }
}
