// Victim selection for worker/monitor.ts's resourceGuardSweep (emergency
// node-RAM guard). Pure so the fairness rule is unit-testable.
//
// Found 2026-10-04 (Palworld ticket, server sausaugepro): the guard always
// rebooted the single largest VM, and a Palworld guest (which grows toward its
// whole plan RAM) is nearly always the largest. With a 45-minute cooldown the
// same customer was rebooted ~hourly (13 times in 40h) while every other VM on
// the node was never touched, and when the cooldown blocked it the guard gave
// up instead of looking at the next candidate. Rule now: skip any server the
// guard already rebooted within the cooldown and take the largest of the REST,
// so the pain rotates and nobody is hit twice in the window.

export type GuardCandidate<T = unknown> = {
  /** Current guest memory use in bytes (PVE `mem`). */
  mem: number;
  /** ISO time of the last guard reboot of this server, if any. */
  lastResourceReboot?: string | null;
  server: T;
};

export const DEFAULT_RESOURCE_REBOOT_COOLDOWN_MS = 6 * 60 * 60_000;

export function resourceRebootCooldownMs(env: NodeJS.ProcessEnv = process.env): number {
  const min = Number(env.NXEON_RESOURCE_REBOOT_COOLDOWN_MIN);
  return Number.isFinite(min) && min >= 1 ? min * 60_000 : DEFAULT_RESOURCE_REBOOT_COOLDOWN_MS;
}

export function inResourceRebootCooldown(iso: string | null | undefined, now: number, cooldownMs: number): boolean {
  const t = iso ? new Date(iso).getTime() : 0;
  return Number.isFinite(t) && t > 0 && now - t < cooldownMs;
}

/** Largest candidate NOT in cooldown, or null when every candidate was rebooted recently. */
export function pickGuardVictim<T>(cands: GuardCandidate<T>[], now: number, cooldownMs: number): GuardCandidate<T> | null {
  const eligible = cands
    .filter((c) => !inResourceRebootCooldown(c.lastResourceReboot, now, cooldownMs))
    .sort((a, b) => b.mem - a.mem);
  return eligible[0] ?? null;
}
EOF
python3 - <<'EOF'
p='worker/monitor.ts'
s=open(p).read()
s=s.replace('''const RESOURCE_REBOOT_COOLDOWN_MS = 45 * 60_000;
const REBOOT_TASK_TIMEOUT_MS''','''const RESOURCE_REBOOT_COOLDOWN_MS = resourceRebootCooldownMs();
const REBOOT_TASK_TIMEOUT_MS''')
old_start=s.index('    const top = candidates[0];')
old_end=s.index('    const memGB =')
new='''    // Largest VM that the guard has NOT already rebooted within the cooldown
    // (lib/resource-guard-pick.ts). The old "always the top consumer" rule hit
    // the same Palworld customer ~hourly while everyone else was untouched.
    const now = Date.now();
    const top = pickGuardVictim(
      candidates.map((c) => ({
        mem: Number(c.vm.mem ?? 0),
        lastResourceReboot: ((c.server!.gameConfig as Record<string, unknown> | null)?._lastResourceReboot as string | undefined) ?? null,
        vm: c.vm,
        server: c.server!,
      })),
      now,
      RESOURCE_REBOOT_COOLDOWN_MS,
    );

    if (!top) {
      // Every tracked VM on this node was already auto-rebooted within the
      // cooldown and the node is STILL critical — rebooting more won't fix an
      // oversubscribed node; a human needs to move/upgrade capacity.
      await notifyNodeCapacity(
        `Node still critical after auto-reboots — ${n.name}`,
        `${n.name} is at ${Math.round(pct)}% RAM and every customer VM on it was already auto-rebooted within ` +
          `the last ${Math.round(RESOURCE_REBOOT_COOLDOWN_MS / 60_000)} minutes. Rebooting more will not help — the node is ` +
          `oversubscribed and needs VMs moved off it or more RAM (check node ZFS ARC cap and swap too).`,
      );
      continue;
    }
    const server = top.server;
    const cfg = (server.gameConfig as Record<string, unknown> | null) ?? {};

'''
s=s[:old_start]+new+s[old_end:]
s=s.replace('const memGB = (Number(top.vm.mem ?? 0)','const memGB = (Number(top.vm.mem ?? 0)')
open(p,'w').write(s)
EOF
