import test from "node:test";
import assert from "node:assert/strict";
import { pickGuardVictim, inResourceRebootCooldown, resourceRebootCooldownMs, DEFAULT_RESOURCE_REBOOT_COOLDOWN_MS } from "../lib/resource-guard-pick";

const NOW = Date.parse("2026-10-04T12:00:00Z");
const ago = (min: number) => new Date(NOW - min * 60_000).toISOString();
const H = DEFAULT_RESOURCE_REBOOT_COOLDOWN_MS;

test("picks the largest VM when nobody was rebooted recently", () => {
  const v = pickGuardVictim([{ mem: 3, id: "a" }, { mem: 9, id: "b" }, { mem: 5, id: "c" }], NOW, H);
  assert.equal(v?.id, "b");
});

test("skips the biggest VM when the guard rebooted it inside the cooldown and takes the next one", () => {
  const v = pickGuardVictim([{ mem: 9, id: "palworld", lastResourceReboot: ago(60) }, { mem: 5, id: "next" }, { mem: 3, id: "small" }], NOW, H);
  assert.equal(v?.id, "next");
});

test("a reboot older than the cooldown makes the VM eligible again", () => {
  const v = pickGuardVictim([{ mem: 9, id: "palworld", lastResourceReboot: ago(7 * 60) }, { mem: 5, id: "x" }], NOW, H);
  assert.equal(v?.id, "palworld");
});

test("returns null when every candidate is in cooldown", () => {
  assert.equal(pickGuardVictim([{ mem: 9, lastResourceReboot: ago(10) }, { mem: 5, lastResourceReboot: ago(20) }], NOW, H), null);
  assert.equal(pickGuardVictim([], NOW, H), null);
});

test("garbage timestamps are treated as no prior reboot", () => {
  assert.equal(inResourceRebootCooldown("not-a-date", NOW, H), false);
  assert.equal(inResourceRebootCooldown(null, NOW, H), false);
});

test("cooldown env override", () => {
  assert.equal(resourceRebootCooldownMs({ NXEON_RESOURCE_REBOOT_COOLDOWN_MIN: "90" } as any), 90 * 60_000);
  assert.equal(resourceRebootCooldownMs({} as any), H);
  assert.equal(resourceRebootCooldownMs({ NXEON_RESOURCE_REBOOT_COOLDOWN_MIN: "0" } as any), H);
});
EOF
